import{_ as o,o as a,c as r,a2 as t}from"./chunks/framework.BDCokyix.js";const p=JSON.parse('{"title":"8. Crosscutting Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/arc42/08-crosscutting.md","filePath":"architecture/arc42/08-crosscutting.md","lastUpdated":1780254295000}'),i={name:"architecture/arc42/08-crosscutting.md"};function s(c,e,n,d,l,u){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="_8-crosscutting-concepts" tabindex="-1">8. Crosscutting Concepts <a class="header-anchor" href="#_8-crosscutting-concepts" aria-label="Permalink to &quot;8. Crosscutting Concepts&quot;">​</a></h1><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><ul><li>The <code>somad</code> server binary uses <code>clap</code> with environment variable support.</li><li>Common env vars include: <ul><li><code>SOMA_BLOB_DIR</code> (blob pool / cache root)</li><li><code>SOMA_LISTEN_ADDRS</code>, <code>SOMA_RDV_ADDRS</code>, <code>SOMA_RELAY_ADDRS</code> (libp2p connectivity)</li><li><code>HTTP_ADDR</code> (server HTTP bind)</li></ul></li><li>The desktop daemon library is configured by the napi addon&#39;s <code>StartConfig</code> (constructed in <code>desktop/soma/src/main/services/addon-runtime.ts</code>); there are no <code>SOMA_*</code> env vars on the desktop side.</li></ul><h2 id="observability" tabindex="-1">Observability <a class="header-anchor" href="#observability" aria-label="Permalink to &quot;Observability&quot;">​</a></h2><ul><li>Server daemons expose: <ul><li><code>GET /healthz</code> → <code>&quot;ok&quot;</code></li><li><code>GET /metrics</code> → Prometheus text format</li></ul></li><li>Rust logging uses <code>tracing</code> with <code>RUST_LOG</code> filtering.</li></ul><h2 id="storage-and-migrations" tabindex="-1">Storage and migrations <a class="header-anchor" href="#storage-and-migrations" aria-label="Permalink to &quot;Storage and migrations&quot;">​</a></h2><ul><li>The desktop daemon library uses a local SQLite database under Electron&#39;s <code>userData/daemon/</code>. Path is configured via the napi addon&#39;s <code>StartConfig.daemonDbPath</code>.</li><li><code>somad bot</code> uses <code>SOMA_DATABASE_URL</code> and supports SQLite or Postgres via SQLx AnyPool.</li><li>Migrations live in <code>backend/crates/storage/migrations</code> and are applied at startup.</li></ul><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><ul><li>The desktop daemon runs in-process inside the Electron main process; there is no public-network or local-IPC API surface to attack. The only inter-process boundary is the renderer ↔ main Electron IPC bridge, which exposes a narrow controller set.</li><li>Capability-based membership avoids accounts/passwords and supports explicit delegation.</li><li>Blob CAS verifies bytes match the claimed CID before persisting/serving.</li></ul><p>See <code>docs/src/security/threat-model.md</code> for the consolidated threat model.</p><h2 id="performance-and-backpressure" tabindex="-1">Performance and backpressure <a class="header-anchor" href="#performance-and-backpressure" aria-label="Permalink to &quot;Performance and backpressure&quot;">​</a></h2><ul><li>Peer event handling uses a dispatcher with bounded per-handler queues to keep the peer loop responsive.</li><li>Blob transfer is currently size-bounded (single message request/response); large blob support requires chunking/streaming.</li></ul>',12)])])}const m=o(i,[["render",s]]);export{p as __pageData,m as default};
